implementation:
#include <stdlib.h>
#include <mutex.h>
#include <idr.h>

struct ucma_multicast {
    int id;
    struct ucma_context* ctx;
    struct list_head list;
};

struct ucma_multicast* ucma_alloc_multicast(struct ucma_context* ctx) {
    struct ucma_multicast* multicast = (struct ucma_multicast*)kzalloc(sizeof(struct ucma_multicast));
    if (!multicast) {
        return NULL;
    }

    mutex_lock(&idr_mutex);
    int id = idr_alloc();
    mutex_unlock(&idr_mutex);

    if (id < 0) {
        kfree(multicast);
        return NULL;
    }

    multicast->id = id;
    multicast->ctx = ctx;

    mutex_lock(&ctx->multicast_mutex);
    list_add(&multicast->list, &ctx->multicast_list);
    mutex_unlock(&ctx->multicast_mutex);

    return multicast;
}
